namespace ghidra.framework.main.datatable;





using ghidra.framework.data;
using ghidra.framework.data.LinkHandler;
using ghidra.framework.main;
using ghidra.framework.main.datatree;
using ghidra.framework.model;

public class DomainFileInfo {

	private DomainFile domainFile;
	private ProjectDataTableModel model;
	private int modCount;
	private string name;
	private string path;
	private Map<string, string> metadata;
	private Date modificationDate;
	private DomainFileType domainFileType;
	private Boolean isBrokenLink;
	private string toolTipText;

	DomainFileInfo(DomainFile domainFile, ProjectDataTableModel model) {
		this.domainFile = domainFile;
		this.model = model;
	}

	private string computeName() {
		string displayName = domainFile.getName();

		if (domainFile.isHijacked()) {
			displayName += " (hijacked)";
		}
		else if (domainFile.isVersioned()) {
			int versionNumber = domainFile.getVersion();
			string versionStr = "" + versionNumber;

			if (versionNumber < 0) {
				versionStr = "?";
			}

			if (domainFile.isCheckedOut()) {
				int latestVersionNumber = domainFile.getLatestVersion();
				string latestVersionStr = "" + latestVersionNumber;
				if (latestVersionNumber <= 0) {
					latestVersionStr = "?";
				}
				displayName += " (" + versionStr + " of " + latestVersionStr + ")";
				if (domainFile.modifiedSinceCheckout()) {
					displayName += "*";
				}
			}
			else {
				displayName += " (" + versionStr + ")";
			}
		}
		return displayName;
	}

	public string getDisplayName() {
		checkModelModCount();
		if (name == null) {
			name = computeName();
		}
		return name;
	}

	public string getPath() {
		checkModelModCount();
		if (path == null) {
			path = domainFile.getParent().getPathname();
		}
		return path;
	}

	public DomainFileType getDomainFileType() {
		checkModelModCount();
		if (domainFileType == null) {
			checkStatus();
			string contentType = domainFile.getContentType();
			Icon icon = domainFile.getIcon(false);
			if (isBrokenLink) {
				icon = new BrokenLinkIcon(icon);
			}
			bool isVersioned = domainFile.isVersioned();
			domainFileType = new DomainFileType(contentType, icon, isVersioned);
		}
		return domainFileType;
	}

	public Date getModificationDate() {
		checkModelModCount();
		if (modificationDate == null) {
			modificationDate = getLastModifiedTime();
		}
		return modificationDate;
	}

	private Date getLastModifiedTime() {
		long lastModified = domainFile.getLastModifiedTime();
		if (lastModified != 0) {
			return new Date(lastModified);
		}
		return new Date();
	}

	private Map<string, string> getMetadata() {
		checkModelModCount();
		if (metadata == null) {
			metadata = domainFile.getMetadata();
			if (metadata == null) {
				metadata = new Dictionary<string, string>();
			}
		}
		return metadata;
	}

	public DomainFile getDomainFile() {
		return domainFile;
	}

	public void clearMetaCache() {
		metadata = null;
		modificationDate = null;
		refresh();
	}

	public void refresh() {
		domainFileType = null;
		isBrokenLink = null;
		toolTipText = null;
		name = null;
		path = null;
	}

	public string getMetaDataValue(string key) {
		Map<string, string> meta = getMetadata();
		return meta.get(key);
	}

	public string getName() {
		return domainFile.getName();
	}

	private void checkModelModCount() {
		int modelModCount = model.getModCount();
		if (modelModCount != modCount) {
			refresh();
			modCount = modelModCount;
		}
	}

	private void checkStatus() {
		checkModelModCount();
		if (isBrokenLink == null) {
			isBrokenLink = false;
			List<string> linkErrors = null;
			if (domainFile.isLink()) {
				List<string> errors = new();
				LinkStatus linkStatus =
					LinkHandler.getLinkFileStatus(domainFile, msg => errors.add(msg));
				isBrokenLink = (linkStatus == LinkStatus.BROKEN);
				if (isBrokenLink) {
					linkErrors = errors;
				}
			}
			toolTipText = DomainFileNode.getToolTipText(domainFile, linkErrors);
		}
	}

	public string getToolTip() {
		checkStatus();
		return toolTipText;
	}

}
